		return lipgloss.NewStyle().
				Width(s.width).
				Render(lipgloss.JoinHorizontal(
					lipgloss.Left,
					styles.PrevIndicator.Faint(s.selected <= 0).String(),
					option,
					styles.NextIndicator.Faint(s.selected == len(s.filteredOptions)-1).String(),
				)),
			-1, 1
